static const char turbo_resources[]="<local:NumUnitConverter x:Key=\"ALS_Number\" FractionDigits=\"0\" ShowUnit=\"False\"/>\n";
static const char turbo_panel[]="<local:CommonListBox x:Name=\"ALS_TurboPanel\" KeyboardNavigation.DirectionalNavigation=\"Contained\" ItemContainerStyle=\"{StaticResource A_Style_ListBoxItem_List_Tuning}\">\n<local:CommonListBox.Style><Style TargetType=\"local:CommonListBox\" BasedOn=\"{StaticResource A_Style_ListBox_List_Tuning}\"><Setter Property=\"IsEnabled\" Value=\"False\"/><Style.Triggers><DataTrigger Binding=\"{Binding TurboEditable, ElementName=ALS_TuningPage}\" Value=\"1\"><Setter Property=\"IsEnabled\" Value=\"True\"/></DataTrigger></Style.Triggers></Style></local:CommonListBox.Style>\n<ItemsControl Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced_Header}\" Focusable=\"False\">\n<local:FZTextBlock Text=\"PRESSURE DECAY (ms)\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"0\"/>\n<local:FZTextBlock Text=\"FAST\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Left\"/>\n<local:FZTextBlock Text=\"SLOW\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Right\"/>\n</ItemsControl>\n<ItemsControl x:Name=\"ALS_DecayRow\" Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced}\" Tag=\"Controls how slowly the stored turbo pressure and spool fade after you release the accelerator. Move towards SLOW for a longer pressure tail, or FAST for a shorter, sharper release. 6000 ms is the default decay scale; it does not guarantee six seconds of anti-lag. The effect can end earlier as boost falls or engine speed drops below the cutoff. Pressing the accelerator again cancels the release effect. Start at the default, then increase this value if the effect ends too quickly.\">\n<local:FZTextBlock Text=\"PRESSURE DECAY (ms)\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" Grid.Column=\"0\"/>\n<Slider x:Name=\"ALS_DecaySlider\" Focusable=\"True\" Minimum=\"1000\" Maximum=\"8000\" SmallChange=\"100\" LargeChange=\"0\" Value=\"{Binding TurboDecay, ElementName=ALS_TuningPage, Mode=TwoWay}\" Style=\"{StaticResource A_Style_Slider_Tuning_Adjust}\" Grid.Column=\"1\" VerticalAlignment=\"Center\" Height=\"20\"/>\n<local:FZTextBlock Text=\"{Binding Value, ElementName=ALS_DecaySlider, Converter={StaticResource ALS_Number}}\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" HorizontalAlignment=\"Right\" Grid.Column=\"2\"/>\n</ItemsControl>\n<ItemsControl Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced_Header}\" Focusable=\"False\">\n<local:FZTextBlock Text=\"BOOST RETENTION (%)\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"0\"/>\n<local:FZTextBlock Text=\"LOW\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Left\"/>\n<local:FZTextBlock Text=\"HIGH\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Right\"/>\n</ItemsControl>\n<ItemsControl x:Name=\"ALS_RetentionRow\" Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced}\" Tag=\"Sets how much of the decaying turbo pressure and spool the mod tries to preserve after you lift off. Move towards HIGH to retain more boost, or LOW for a weaker hold. This percentage is applied to the pressure that remains as it decays, rather than holding peak boost constant. It does not directly increase engine power, sound volume or change the sound sample. The default is 85%. Tune this together with pressure decay to balance a strong response with a gradual release.\">\n<local:FZTextBlock Text=\"BOOST RETENTION (%)\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" Grid.Column=\"0\"/>\n<Slider x:Name=\"ALS_RetentionSlider\" Focusable=\"True\" Minimum=\"25\" Maximum=\"95\" SmallChange=\"1\" LargeChange=\"0\" Value=\"{Binding TurboRetention, ElementName=ALS_TuningPage, Mode=TwoWay}\" Style=\"{StaticResource A_Style_Slider_Tuning_Adjust}\" Grid.Column=\"1\" VerticalAlignment=\"Center\" Height=\"20\"/>\n<local:FZTextBlock Text=\"{Binding Value, ElementName=ALS_RetentionSlider, Converter={StaticResource ALS_Number}}\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" HorizontalAlignment=\"Right\" Grid.Column=\"2\"/>\n</ItemsControl>\n<ItemsControl Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced_Header}\" Focusable=\"False\">\n<local:FZTextBlock Text=\"CUTOFF RPM\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"0\"/>\n<local:FZTextBlock Text=\"LOW\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Left\"/>\n<local:FZTextBlock Text=\"HIGH\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Right\"/>\n</ItemsControl>\n<ItemsControl x:Name=\"ALS_CutoffRow\" Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced}\" Tag=\"Sets the minimum engine speed at which anti-lag may remain active. Move towards LOW to let the effect continue further down the rev range; move towards HIGH to stop it earlier as the engine slows. The default is 1800 RPM. Charging the effect also requires engine speed at least 700 RPM above this setting, sufficient throttle and boost. A high cutoff can therefore make activation harder. A low cutoff does not force backfire at idle: boost and throttle conditions still apply.\">\n<local:FZTextBlock Text=\"CUTOFF RPM\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" Grid.Column=\"0\"/>\n<Slider x:Name=\"ALS_CutoffSlider\" Focusable=\"True\" Minimum=\"1000\" Maximum=\"6000\" SmallChange=\"100\" LargeChange=\"0\" Value=\"{Binding TurboCutoff, ElementName=ALS_TuningPage, Mode=TwoWay}\" Style=\"{StaticResource A_Style_Slider_Tuning_Adjust}\" Grid.Column=\"1\" VerticalAlignment=\"Center\" Height=\"20\"/>\n<local:FZTextBlock Text=\"{Binding Value, ElementName=ALS_CutoffSlider, Converter={StaticResource ALS_Number}}\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" HorizontalAlignment=\"Right\" Grid.Column=\"2\"/>\n</ItemsControl>\n<ItemsControl Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced_Header}\" Focusable=\"False\">\n<local:FZTextBlock Text=\"POP INTERVAL (ms)\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"0\"/>\n<local:FZTextBlock Text=\"FAST\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Left\"/>\n<local:FZTextBlock Text=\"SLOW\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemTitle}\" Grid.Column=\"1\" HorizontalAlignment=\"Right\"/>\n</ItemsControl>\n<ItemsControl x:Name=\"ALS_PopRow\" Style=\"{StaticResource A_Style_ItemsControl_1x3_TuningSpaced}\" Tag=\"Controls the base time between backfire pulses while anti-lag is active. Move towards FAST for closer, more frequent pops, or SLOW for wider gaps. A smaller number means a faster cadence: 100 ms is faster than 500 ms. The actual gap grows as stored boost and engine speed fall, so this value is not a fixed firing interval. The default is 140 ms. This changes the rhythm of the game's native backfire events, not the sound sample or its volume.\">\n<local:FZTextBlock Text=\"POP INTERVAL (ms)\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" Grid.Column=\"0\"/>\n<Slider x:Name=\"ALS_PopSlider\" Focusable=\"True\" Minimum=\"100\" Maximum=\"500\" SmallChange=\"10\" LargeChange=\"0\" Value=\"{Binding TurboPop, ElementName=ALS_TuningPage, Mode=TwoWay}\" Style=\"{StaticResource A_Style_Slider_Tuning_Adjust}\" Grid.Column=\"1\" VerticalAlignment=\"Center\" Height=\"20\"/>\n<local:FZTextBlock Text=\"{Binding Value, ElementName=ALS_PopSlider, Converter={StaticResource ALS_Number}}\" Style=\"{StaticResource A_Style_FZTextBlock_Tune_ItemLabel}\" HorizontalAlignment=\"Right\" Grid.Column=\"2\"/>\n</ItemsControl>\n</local:CommonListBox>\n";
static const char turbo_state[]="<VisualState x:Name=\"VisualState_Turbo\"><Storyboard>\n<ObjectAnimationUsingKeyFrames Storyboard.TargetName=\"ALS_TurboPanel\" Storyboard.TargetProperty=\"(UIElement.Visibility)\"><DiscreteObjectKeyFrame KeyTime=\"0\" Value=\"{x:Static Visibility.Visible}\"/></ObjectAnimationUsingKeyFrames>\n<ObjectAnimationUsingKeyFrames Storyboard.TargetName=\"ALS_TurboPanel\" Storyboard.TargetProperty=\"(UIElement.Focusable)\"><DiscreteObjectKeyFrame KeyTime=\"0\" Value=\"True\"/></ObjectAnimationUsingKeyFrames>\n<ObjectAnimationUsingKeyFrames Storyboard.TargetName=\"ALS_TurboHelp\" Storyboard.TargetProperty=\"(UIElement.Visibility)\"><DiscreteObjectKeyFrame KeyTime=\"0\" Value=\"{x:Static Visibility.Visible}\"/></ObjectAnimationUsingKeyFrames>\n</Storyboard></VisualState>\n";
static const char turbo_help[]="<Grid x:Name=\"ALS_TurboHelp\" Visibility=\"Hidden\" Margin=\"30,20\">\n<local:FZTextBlock Text=\"Controls how slowly the stored turbo pressure and spool fade after you release the accelerator. Move towards SLOW for a longer pressure tail, or FAST for a shorter, sharper release. 6000 ms is the default decay scale; it does not guarantee six seconds of anti-lag. The effect can end earlier as boost falls or engine speed drops below the cutoff. Pressing the accelerator again cancels the release effect. Start at the default, then increase this value if the effect ends too quickly. Settings are saved for this car model. Load Default tuning settings to restore the anti-lag defaults. Anti-lag is automatically active with the special turbo equipped.\"><local:FZTextBlock.Style><Style TargetType=\"local:FZTextBlock\" BasedOn=\"{StaticResource A_Style_FZTextBlock_Tuning_DescriptionBlockBody}\"><Setter Property=\"Visibility\" Value=\"Collapsed\"/><Style.Triggers><DataTrigger Binding=\"{Binding IsKeyboardFocusWithin, ElementName=ALS_DecayRow}\" Value=\"True\"><Setter Property=\"Visibility\" Value=\"Visible\"/></DataTrigger></Style.Triggers></Style></local:FZTextBlock.Style></local:FZTextBlock>\n<local:FZTextBlock Text=\"Sets how much of the decaying turbo pressure and spool the mod tries to preserve after you lift off. Move towards HIGH to retain more boost, or LOW for a weaker hold. This percentage is applied to the pressure that remains as it decays, rather than holding peak boost constant. It does not directly increase engine power, sound volume or change the sound sample. The default is 85%. Tune this together with pressure decay to balance a strong response with a gradual release. Settings are saved for this car model. Load Default tuning settings to restore the anti-lag defaults. Anti-lag is automatically active with the special turbo equipped.\"><local:FZTextBlock.Style><Style TargetType=\"local:FZTextBlock\" BasedOn=\"{StaticResource A_Style_FZTextBlock_Tuning_DescriptionBlockBody}\"><Setter Property=\"Visibility\" Value=\"Collapsed\"/><Style.Triggers><DataTrigger Binding=\"{Binding IsKeyboardFocusWithin, ElementName=ALS_RetentionRow}\" Value=\"True\"><Setter Property=\"Visibility\" Value=\"Visible\"/></DataTrigger></Style.Triggers></Style></local:FZTextBlock.Style></local:FZTextBlock>\n<local:FZTextBlock Text=\"Sets the minimum engine speed at which anti-lag may remain active. Move towards LOW to let the effect continue further down the rev range; move towards HIGH to stop it earlier as the engine slows. The default is 1800 RPM. Charging the effect also requires engine speed at least 700 RPM above this setting, sufficient throttle and boost. A high cutoff can therefore make activation harder. A low cutoff does not force backfire at idle: boost and throttle conditions still apply. Settings are saved for this car model. Load Default tuning settings to restore the anti-lag defaults. Anti-lag is automatically active with the special turbo equipped.\"><local:FZTextBlock.Style><Style TargetType=\"local:FZTextBlock\" BasedOn=\"{StaticResource A_Style_FZTextBlock_Tuning_DescriptionBlockBody}\"><Setter Property=\"Visibility\" Value=\"Collapsed\"/><Style.Triggers><DataTrigger Binding=\"{Binding IsKeyboardFocusWithin, ElementName=ALS_CutoffRow}\" Value=\"True\"><Setter Property=\"Visibility\" Value=\"Visible\"/></DataTrigger></Style.Triggers></Style></local:FZTextBlock.Style></local:FZTextBlock>\n<local:FZTextBlock Text=\"Controls the base time between backfire pulses while anti-lag is active. Move towards FAST for closer, more frequent pops, or SLOW for wider gaps. A smaller number means a faster cadence: 100 ms is faster than 500 ms. The actual gap grows as stored boost and engine speed fall, so this value is not a fixed firing interval. The default is 140 ms. This changes the rhythm of the game's native backfire events, not the sound sample or its volume. Settings are saved for this car model. Load Default tuning settings to restore the anti-lag defaults. Anti-lag is automatically active with the special turbo equipped.\"><local:FZTextBlock.Style><Style TargetType=\"local:FZTextBlock\" BasedOn=\"{StaticResource A_Style_FZTextBlock_Tuning_DescriptionBlockBody}\"><Setter Property=\"Visibility\" Value=\"Collapsed\"/><Style.Triggers><DataTrigger Binding=\"{Binding IsKeyboardFocusWithin, ElementName=ALS_PopRow}\" Value=\"True\"><Setter Property=\"Visibility\" Value=\"Visible\"/></DataTrigger></Style.Triggers></Style></local:FZTextBlock.Style></local:FZTextBlock>\n</Grid>\n";
